@startuml

class User {
  + id : int
  + name : string
  + email : string
  + dateOfBirth : date
}

class Account {
  + accountNumber : string
}

abstract class PersonalAccount {
}

abstract class BusinessAccount {
  + companyName : string
  + monthlyFee : double
}

class Page {
  + pageName : string
  + visitCount : int
}

class AdvertisementPage {
  + bounceRate : float
  + clickThroughRate : float
  + conversionRate : float
}

class FriendRequest {
  + status : string
}

User "1" *-- "1" Account
Account --|> PersonalAccount
Account --|> BusinessAccount
PersonalAccount "1" -- "*" PersonalAccount : friend
PersonalAccount "1" -- "*" FriendRequest
Account "1" *-- "*" Page
BusinessAccount "1" *-- "*" AdvertisementPage
AdvertisementPage --|> Page
PersonalAccount "0..*" -- "*" Page : privilege
@enduml

